;------------------------------------------------------------; Start.m; This file contains macros and data structures used by Start;------------------------------------------------------------tMessage	record	0next		ds.l	1		; handle to next messagetype		ds.w	1		; type (ID) of messagedata		ds.w	1		; message datasize		endrtDateTime	record	0sec		ds.b	1min		ds.b	1hour		ds.b	1year		ds.b	1day		ds.b	1month		ds.b	1		ds.b	1weekday		ds.b	1		endrtControl	record	0pcount		ds.w	1		; pCount (min = 5)dev_num		ds.w	1		; device numberctl_code	ds.w	1		; control codectl_list	ds.l	1		; pointer to control listreq_cnt		ds.l	1		; request counttrans_cnt	ds.l	1		; transfer count		endrtOpen		record	0pcount		ds.w	1		; pCount (min = 2)refnum		ds.w	1		; open file refnumpath		ds.l	1		; pathname pointerreq_acc		ds.w	1		; requested accessres_num		ds.w	1		; resource numberaccess		ds.w	1		; file's access wordfile_type	ds.w	1		; file's file typeaux_type	ds.l	1		; file's aux typestor_type	ds.w	1		; file's storage typecr_date		ds	tDateTime	; file's create date/timemod_date	ds	tDateTime	; file's modification date/timeopt_list	ds.l	1		; option list pointerdata_eof	ds.l	1		; data fork EOFdata_blks	ds.l	1		; data fork blocks usedres_eof		ds.l	1		; resource fork EOFres_blks	ds.l	1		; resource fork blocks used		endrtRead		record	0pcount		ds.w	1		; pCount (min = 4)refnum		ds.w	1		; open file refnumbuf_addr	ds.l	1		; data buffer addressreq_cnt		ds.l	1		; requested amounttrans_cnt	ds.l	1		; actual transfer amountpriority	ds.w	1		; cache priority		endrtClose		record	0pcount		ds.w	1		; pCount (min = 1)refnum		ds.w	1		; open file refnum		endrtSetMark	record	0pcount		ds.w	1		; pCount (min = 3)refnum		ds.w	1		; open file refnumbase		ds.w	1		; base for displacementdisp		ds.l	1		; displacement (relative to base)		endrtGetDirEntry	record	0pcount		ds.w	1		; pCount (min = 5)refnum		ds.w	1		; open file refnumflags		ds.w	1		; high bit set if extended filebase		ds.w	1		; base of displacementdisp		ds.w	1		; displacement (relative to base)name		ds.l	1		; pointer to name bufferentry_num	ds.w	1		; entry number in directoryfile_type	ds.w	1		; file's file typedata_eof	ds.l	1		; data fork EOFdata_blks	ds.l	1		; data fork blocks usedcr_date		ds	tDateTime	; file's create date/timemod_date	ds	tDateTime	; file's modified date/timeaccess		ds.w	1		; file's access wordaux_type	ds.l	1		; file's aux typefile_sys_id	ds.w	1		; file system typeopt_list	ds.l	1		; pointer to option listres_eof		ds.l	1		; resource fork EOFres_blks	ds.l	1		; resource fork blocks used		endrtDInfo		record	0pcount		ds.w	1		; pCount (min =2)dev_num		ds.w	1		; device numberdev_name	ds.l	1		; pointer to device name bufferchar		ds.w	1		; device characteristicstot_blks	ds.l	1		; total blocksslot_num	ds.w	1		; device slot numberunit_num	ds.w	1		; device unit numberversion		ds.w	1		; version of driverdev_type	ds.w	1		; type of devicehead_link	ds.w	1		; device number of head of linked listnext_link	ds.w	1		; device number of next device in list		endrtFSTInfo	record	0pcount		ds.w	1		; pCount (min = 2)fst_num		ds.w	1		; FST numbers 1, 2, 3, ...file_sys_id	ds.w	1		; file system number ($0D for AppleShare)version		ds.w	1		; version of FSTattributes	ds.w	1		; FST attributesblock_size	ds.w	1		; size of blocks in bytesmax_vol_size	ds.l	1		; maximum volume size in blocksmax_file_size	ds.l	1		; maximum file size in bytes		endrtLevel		record	0pcount		ds.w	1		; pcount (min=1)level		ds.w	1		; user leveluserflag	ds.w	1		; $8000 set if user level		endr		tFSTSetStar	record	0pcount		ds.w	1		; pcount (min=3)fst_id		ds.w	1		; FST ID (=$0D for AppleShare)callnum		ds.w	1		; FST specific call # ($4D44)dp		ds.w	1		; result: GS/OS direct page address		endr		; This is the format of the ATINIT file:tATINIT		record	0		ds.b	1		; RESERVED, also used to check access					; to startup application		ds.b	6		; path volID and dirIDPath		ds.b	65		; user's startup application		ds.b	6		; prefix volID and dirIDPrefix		ds.b	65		; user's startup prefix		ds.b	33		; user name, unused herePFlags		ds.b	1		; Printer flags at startupPEntity		ds.b	99		; printer tuplesize		endr